{"hypotheses": [
  {
   "name": "Hypothesis 1",
   "mechanism": "Firms with high ROA and low volatility are likely to be fundamentally strong, and their performance can be further bolstered by high customer momentum.",
   "expression": {
       "terms": [{"weight": 1, "primitive": "roaq"}, {"weight": -0.5, "primitive": "RealizedVol"}, {"weight": 0.5, "primitive": "iomom_cust"}],
       "regime": "MKT_TRAILING_12M_UP",
       "vol_target": true
   },
   "auxiliary_predictions": [
       {"type": "size_segment", "segment": "large", "direction": "stronger"},
       {"type": "correlation", "primitive": "Size", "bound": "below", "threshold": 0.3},
       {"type": "subperiod_consistency"}
   ],
   "expected_annualized_sharpe": 0.85,
   "expected_decay_half_life_months": 60
  },
  {
   "name": "Hypothesis 2",
   "mechanism": "High advertising expense growth and R&D ability may signal a firm's commitment to innovation and brand visibility, which can be beneficial in a bullish market.",
   "expression": {
       "terms": [{"weight": 0.5, "primitive": "GrAdExp"}, {"weight": 0.5, "primitive": "RDAbility"}],
       "regime": "MKT_TRAILING_12M_UP",
       "vol_target": false
   },
   "auxiliary_predictions": [
       {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
       {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
       {"type": "correlation", "primitive": "Beta", "bound": "above", "threshold": 0.3}
   ], 
   "expected_annualized_sharpe": 0.7,
   "expected_decay_half_life_months": 48
  },
  {
   "name": "Hypothesis 3",
   "mechanism": "Firms with a high equity duration and low idiosyncratic risk might be more attractive to conservative investors, especially in a bearish market.",
   "expression": {
       "terms": [{"weight": 0.5, "primitive": "EquityDuration"}, {"weight": -0.5, "primitive": "IdioVolAHT"}],
       "regime": "MKT_TRAILING_12M_DOWN",
       "vol_target": true
   },
   "auxiliary_predictions": [
       {"type": "size_segment", "segment": "mega", "direction": "stronger"},
       {"type": "subperiod_consistency"},
       {"type": "international", "region": "emerging", "direction": "same_sign"}
   ],
   "expected_annualized_sharpe": 0.8,
   "expected_decay_half_life_months": null
  },
  {
   "name": "Hypothesis 4",
   "mechanism": "A combination of high cash productivity and high customer momentum might indicate a well-managed firm with a loyal consumer base, which should thrive irrespective of the market regime.",
   "expression": {
       "terms": [{"weight": 0.5, "primitive": "CashProd"}, {"weight": 0.5, "primitive": "iomom_cust"}],
       "regime": null,
       "vol_target": true
   },
   "auxiliary_predictions": [
       {"type": "size_segment", "segment": "small", "direction": "stronger"},
       {"type": "correlation", "primitive": "Beta", "bound": "below", "threshold": 0.3},
       {"type": "subperiod_consistency"}
   ],
   "expected_annualized_sharpe": 0.9,
   "expected_decay_half_life_months": 72
  },
  {
   "name": "Hypothesis 5",
   "mechanism": "Firms which are innovative (high R&D ability) and risk averse (low beta) may be poised to perform well, especially in volatile markets.",
   "expression": {
       "terms": [{"weight": 0.5, "primitive": "RDAbility"}, {"weight": -0.5, "primitive": "Beta"}],
       "regime": "VIX_ABOVE_TRAILING_MEDIAN",
       "vol_target": true
   },
   "auxiliary_predictions": [
       {"type": "size_segment", "segment": "large", "direction": "stronger"},
       {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
       {"type": "subperiod_consistency"}
   ],
   "expected_annualized_sharpe": 0.8,
   "expected_decay_half_life_months": 60
  },
  {
   "name": "Hypothesis 6",
   "mechanism": "Consensus recommendation combined with low idiosyncratic risk can act as an indicator of strong fundamentals and lower risk, beneficial in a bear market.",
   "expression": {
       "terms": [{"weight": 0.5, "primitive": "ConsRecomm"}, {"weight": -0.5, "primitive": "IdioVol3F"}],
       "regime": "MKT_TRAILING_12M_DOWN",
       "vol_target": false
   },
   "auxiliary_predictions": [
       {"type": "size_segment", "segment": "mega", "direction": "stronger"},
       {"type": "correlation", "primitive": "Size", "bound": "below", "threshold": 0.3},
       {"type": "subperiod_consistency"}
   ],
   "expected_annualized_sharpe": 0.7,
   "expected_decay_half_life_months": 36
  },
  {
   "name": "Hypothesis 7",
   "mechanism": "Firms with high asset growth and low bid-ask spread are likely to be growing and highly liquid, which can be advantageous in a bullish market.",
   "expression": {
       "terms": [{"weight": 1, "primitive": "AssetGrowth"}, {"weight": -0.5, "primitive": "BidAskSpread"}],
       "regime": "MKT_TRAILING_12M_UP",
       "vol_target": true
   },
   "auxiliary_predictions": [
       {"type": "size_segment", "segment": "small", "direction": "stronger"},
       {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
       {"type": "subperiod_consistency"}
   ],
   "expected_annualized_sharpe": 0.85,
   "expected_decay_half_life_months": 60
  },
  {
   "name": "Hypothesis 8",
   "mechanism": "Firms with a high book to market ratio and low volatility are likely to be underestimated and fundamentally strong, especially during volatile periods.",
   "expression": {
       "terms": [{"weight": 0.5, "primitive": "BM"}, {"weight": -0.5, "primitive": "RealizedVol"}],
       "regime": "VIX_ABOVE_TRAILING_MEDIAN",
       "vol_target": false
   },
   "auxiliary_predictions": [
       {"type": "size_segment", "segment": "large", "direction": "stronger"},
       {"type": "correlation", "primitive": "Size", "bound": "below", "threshold": 0.3},
       {"type": "subperiod_consistency"}
   ],
   "expected_annualized_sharpe": 0.75,
   "expected_decay_half_life_months": 48
  }
]}
